import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"58、【兌】 兌下兌上","description":"橫渠易說 - 58、【兌】 兌下兌上","frontmatter":{"title":"58、【兌】 兌下兌上","description":"橫渠易說 - 58、【兌】 兌下兌上"},"headers":[],"relativePath":"classics/hengqu/060.md","filePath":"classics/hengqu/060.md"}'),l={name:"classics/hengqu/060.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_58、【兌】-兌下兌上" tabindex="-1">58、【兌】 兌下兌上 <a class="header-anchor" href="#_58、【兌】-兌下兌上" aria-label="Permalink to “58、【兌】 兌下兌上”">​</a></h1><h3 id="彖曰-兌-說也-剛中而柔外-說以利貞-是以順乎天而應乎人。說以先民-民忘其勞-說以犯難-民忘其死。說之大-民勸矣哉" tabindex="-1">彖曰：兌，說也，剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞；說以犯難，民忘其死。說之大，民勸矣哉! <a class="header-anchor" href="#彖曰-兌-說也-剛中而柔外-說以利貞-是以順乎天而應乎人。說以先民-民忘其勞-說以犯難-民忘其死。說之大-民勸矣哉" aria-label="Permalink to “彖曰：兌，說也，剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞；說以犯難，民忘其死。說之大，民勸矣哉!”">​</a></h3><h3 id="象曰-麗澤兌-君子以朋友講習。" tabindex="-1">象曰：麗澤兌，君子以朋友講習。 <a class="header-anchor" href="#象曰-麗澤兌-君子以朋友講習。" aria-label="Permalink to “象曰：麗澤兌，君子以朋友講習。”">​</a></h3><h3 id="初九-和兌-吉。-象曰-和兌之吉-行未疑也。" tabindex="-1">初九，和兌，吉。 象曰：和兌之吉，行未疑也。 <a class="header-anchor" href="#初九-和兌-吉。-象曰-和兌之吉-行未疑也。" aria-label="Permalink to “初九，和兌，吉。 象曰：和兌之吉，行未疑也。”">​</a></h3><p>以陽居下，無所比附，出門同人，行自信者也。</p><h3 id="九二-孚兌-吉-悔亡。-象曰-孚兌之吉-信志也。" tabindex="-1">九二，孚兌，吉，悔亡。 象曰：孚兌之吉，信志也。 <a class="header-anchor" href="#九二-孚兌-吉-悔亡。-象曰-孚兌之吉-信志也。" aria-label="Permalink to “九二，孚兌，吉，悔亡。 象曰：孚兌之吉，信志也。”">​</a></h3><p>私繫於近，悔也。誠於接物，信而不妄，吉且悔亡。</p><h3 id="六三-來兌-兇。-象曰-來兌之兇-位不當也。" tabindex="-1">六三，來兌，兇。 象曰：來兌之兇，位不當也。 <a class="header-anchor" href="#六三-來兌-兇。-象曰-來兌之兇-位不當也。" aria-label="Permalink to “六三，來兌，兇。 象曰：來兌之兇，位不當也。”">​</a></h3><h3 id="九四-商兌未寧-介疾有喜。-象曰-九四之喜-有慶也。" tabindex="-1">九四，商兌未寧，介疾有喜。 象曰：九四之喜，有慶也。 <a class="header-anchor" href="#九四-商兌未寧-介疾有喜。-象曰-九四之喜-有慶也。" aria-label="Permalink to “九四，商兌未寧，介疾有喜。 象曰：九四之喜，有慶也。”">​</a></h3><p>通其邪佞，使進而上，則小人道長而不寧，以諂為疾而拒外之，則終不失其得偶之慶也。</p><h3 id="九五-孚於剝-有厲。-象曰-孚於剝-位正當也。" tabindex="-1">九五，孚於剝，有厲。 象曰：“孚於剝”，位正當也。 <a class="header-anchor" href="#九五-孚於剝-有厲。-象曰-孚於剝-位正當也。" aria-label="Permalink to “九五，孚於剝，有厲。 象曰：“孚於剝”，位正當也。”">​</a></h3><p>說六三之進，則是孚於剝，近危之道也。故處乎盛位者，佞不可親也，當正位而進小人，信乎剝之道也。</p><h3 id="上六-引兌。-象曰-上六引兌-未光也。" tabindex="-1">上六，引兌。 象曰：“上六引兌”，未光也。 <a class="header-anchor" href="#上六-引兌。-象曰-上六引兌-未光也。" aria-label="Permalink to “上六，引兌。 象曰：“上六引兌”，未光也。”">​</a></h3><p>與三為類而引升之，雖不傷類，然未足多也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
